def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    stack: set[str] = set()

    def is_err(v: int | str) -> bool:
        return isinstance(v, str)

    def trunc_div(a: int, b: int) -> int | str:
        if b == 0:
            return "#DIV/0!"
        sign = 1 if (a < 0) == (b < 0) else -1
        return sign * (abs(a) // abs(b))

    def range_names(a: str, b: str):
        c1, r1 = ord(a[0]), int(a[1:])
        c2, r2 = ord(b[0]), int(b[1:])
        for r in range(min(r1, r2), max(r1, r2) + 1):
            for c in range(min(c1, c2), max(c1, c2) + 1):
                yield chr(c) + str(r)

    def compare(a: int, op: str, b: int) -> bool:
        if op == "=":
            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b

    def eval_cell(name: str) -> int | str:
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in stack:
            return "#CYCLE!"
        stack.add(name)
        text = cells[name].strip()
        if text.startswith("="):
            val = eval_node(parse(text[1:]))
        else:
            val = int(text)
        stack.remove(name)
        memo[name] = val
        return val

    def eval_node(node) -> int | str:
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return eval_cell(node[1])
        if kind == "neg":
            v = eval_node(node[1])
            return v if is_err(v) else -v
        if kind == "bin":
            op, left, right = node[1], node[2], node[3]
            lv = eval_node(left)
            if is_err(lv):
                return lv
            rv = eval_node(right)
            if is_err(rv):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            return trunc_div(lv, rv)
        if kind == "if":
            lv = eval_node(node[1])
            if is_err(lv):
                return lv
            rv = eval_node(node[3])
            if is_err(rv):
                return rv
            chosen = node[4] if compare(lv, node[2], rv) else node[5]
            return eval_node(chosen)
        vals: list[int] = []
        for arg in node[1]:
            if arg[0] == "range":
                for name in range_names(arg[1], arg[2]):
                    if name not in cells:
                        continue
                    v = eval_cell(name)
                    if is_err(v):
                        return v
                    vals.append(v)
            else:
                v = eval_node(arg)
                if is_err(v):
                    return v
                vals.append(v)
        if not vals:
            return 0
        if kind == "sum":
            return sum(vals)
        if kind == "min":
            return min(vals)
        return max(vals)

    def parse(s: str):
        n = len(s)
        p = [0]

        def skip() -> None:
            while p[0] < n and s[p[0]] == " ":
                p[0] += 1

        def parse_expr():
            left = parse_term()
            while True:
                skip()
                if p[0] < n and s[p[0]] in "+-":
                    op = s[p[0]]
                    p[0] += 1
                    right = parse_term()
                    left = ("bin", op, left, right)
                else:
                    break
            return left

        def parse_term():
            left = parse_unary()
            while True:
                skip()
                if p[0] < n and s[p[0]] in "*/":
                    op = s[p[0]]
                    p[0] += 1
                    right = parse_unary()
                    left = ("bin", op, left, right)
                else:
                    break
            return left

        def parse_unary():
            skip()
            if p[0] < n and s[p[0]] == "-":
                p[0] += 1
                return ("neg", parse_unary())
            return parse_atom()

        def read_number() -> int:
            start = p[0]
            while p[0] < n and s[p[0]].isdigit():
                p[0] += 1
            return int(s[start:p[0]])

        def read_cell() -> str:
            skip()
            col = s[p[0]]
            p[0] += 1
            return col + str(read_number())

        def is_range() -> bool:
            j = p[0]
            while j < n and s[j] == " ":
                j += 1
            if j >= n or not ("A" <= s[j] <= "Z"):
                return False
            j += 1
            if j >= n or not s[j].isdigit():
                return False
            while j < n and s[j].isdigit():
                j += 1
            while j < n and s[j] == " ":
                j += 1
            return j < n and s[j] == ":"

        def parse_atom():
            skip()
            ch = s[p[0]]
            if ch.isdigit():
                return ("num", read_number())
            if ch == "(":
                p[0] += 1
                node = parse_expr()
                skip()
                p[0] += 1
                return node
            start = p[0]
            while p[0] < n and s[p[0]].isalpha():
                p[0] += 1
            word = s[start:p[0]]
            if word in ("SUM", "MIN", "MAX", "IF"):
                j = p[0]
                while j < n and s[j] == " ":
                    j += 1
                if j < n and s[j] == "(":
                    p[0] = j + 1
                    if word == "IF":
                        return parse_if()
                    return (word.lower(), parse_arglist())
            return ("cell", word + str(read_number()))

        def parse_arg():
            if is_range():
                a = read_cell()
                skip()
                p[0] += 1
                b = read_cell()
                return ("range", a, b)
            return parse_expr()

        def parse_arglist():
            args = [parse_arg()]
            while True:
                skip()
                if s[p[0]] == ",":
                    p[0] += 1
                    args.append(parse_arg())
                else:
                    p[0] += 1
                    break
            return args

        def read_op() -> str:
            skip()
            two = s[p[0]:p[0] + 2]
            if two in ("<>", "<=", ">="):
                p[0] += 2
                return two
            op = s[p[0]]
            p[0] += 1
            return op

        def parse_if():
            left = parse_expr()
            op = read_op()
            right = parse_expr()
            skip()
            p[0] += 1
            then_b = parse_expr()
            skip()
            p[0] += 1
            else_b = parse_expr()
            skip()
            p[0] += 1
            return ("if", left, op, right, then_b, else_b)

        return parse_expr()

    return {name: eval_cell(name) for name in cells}
